const clientes = $('Webhook Clientes').all().map(item => item.json.body || item.json);

const recomendacoes = {
  'Conservador': 'Recomendamos Tesouro Selic e CDB de liquidez diária, priorizando segurança e reserva de emergência.',
  'Moderado': 'Recomendamos Fundos Imobiliários (FIIs) e Tesouro IPCA+ para crescimento sustentável com controle de risco.',
  'Arrojado': 'Recomendamos Ações de valor e dividendos, além de ETFs globais para maior rentabilidade no longo prazo.'
};

return clientes.map(cliente => {
  const perfil = cliente.perfil || 'Conservador';
  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: perfil,
      mensagem: `Olá, ${cliente.nome}! Para o seu perfil ${perfil} com saldo de R$ ${cliente.saldo}, a recomendação é: ${recomendacoes[perfil] || recomendacoes['Conservador']}`
    }
  };
});
